function productCapabilityEvidence(recipeId){
 const s=SCP.state,c=s.portfolio.customers.find(c=>c.id==='starter-customer')?.root,p=s.providerCampaign.projects.find(p=>p.operationId===recipeId&&p.status==='complete');
 if(!c||!p)return null;const deploymentId='d-'+recipeId,d=c.products?.deployments.find(d=>d.id===deploymentId);if(!d?.effective)return null;
 const jobs=s.providerCampaign.jobs.filter(j=>j.customerId==='starter-customer'&&j.status==='completed'&&j.arrivalAt>=p.completedAt),pairs=jobs.map(job=>({job,interaction:c.interactions.find(i=>i.id===job.interactionId)})).filter(x=>x.interaction?.phase==='resolved'&&x.interaction.caseId===x.job.caseId);
 const accepted=i=>i.trace.some(t=>t.code==='PRODUCT_FEATURE_ACCEPTED'&&t.bindings?.some(b=>b.deploymentId===deploymentId));
 const acceptedFeatures=(i,features)=>features.every(feature=>i.trace.some(t=>t.code==='PRODUCT_FEATURE_ACCEPTED'&&t.bindings?.some(b=>b.deploymentId===deploymentId&&b.feature===feature)));
 const base={recipeId,projectId:p.id,completedAt:p.completedAt,deploymentId,sourceIds:[],scope:'actual-paid-product-service; limitation evidence is reported separately'};
 const result=x=>structuredClone({...base,...x});
 if(['ms-workplace-calling','cisco-suite-calling','cisco-dedicated-uc','ms-local-deployment','ms-government-boundary','cisco-government-boundary'].includes(recipeId)){
  const pair=pairs.find(({job,interaction:i})=>job.channel==='voice'&&i.usageMinutes>0&&accepted(i)&&(recipeId!=='cisco-dedicated-uc'||i.from==='alex'&&i.voicePath?.platform==='dedicated-platform')&&(recipeId!=='ms-local-deployment'||i.providerContext?.connected===false));if(!pair)return null;
  const proofs=(c.productEvidence?.requests||[]).filter(r=>r.effective&&r.revokedAt===null&&r.desired?.deploymentId===deploymentId);
  if(recipeId.includes('government')&&proofs.length<2)return null;
  return result({kind:recipeId==='ms-local-deployment'?'offline-bound-local-voice':'bound-duration-bearing-voice',...pair,proofs,local:recipeId==='ms-local-deployment'?{phone:c.resources.phone.effective.local,identity:c.resources.identity.effective.local,continuity:c.providerContinuity}:null});
 }
 if(['ms-meetings-room','cisco-meetings-interoperability'].includes(recipeId)){
  const session=c.information?.meetingSessions.find(m=>m.status==='completed'&&m.startedAt>=p.completedAt&&m.endedAt>m.startedAt),booking=c.information?.bookings.find(b=>b.id===session?.bookingId);if(!session||!booking)return null;
  if(recipeId==='cisco-meetings-interoperability'&&!(c.resources.room.effective.mode==='bridge'&&c.resources.room.effective.interop&&c.information.meeting.effective.bridgeLicensed))return null;
  return result({kind:'duration-bearing-room-session',session,booking,room:c.resources.room.effective,meeting:c.information.meeting.effective,distinctPlatformJoin:c.information.meeting.effective.platform!==c.information.meeting.effective.nativePlatform});
 }
 if(recipeId==='ms-contact-centre'){
  const pair=pairs.find(({job,interaction:i})=>job.channel==='message'&&i.context&&i.agent&&c.cases[i.caseId]?.interactions.includes(i.id)&&acceptedFeatures(i,['omnichannel-routing','customer-records']));if(!pair)return null;
  return result({kind:'staffed-digital-case',...pair,case:c.cases[pair.job.caseId],people:c.workforceOps?.roster.effective,entitlements:c.resources.people.effective.entitlements});
 }
 if(['ms-communications-api','cisco-programmable-engagement'].includes(recipeId)){
  const account=recipeId==='ms-communications-api'?'workplace':'chatterleaf';
  for(const pair of pairs){const i=pair.interaction;if(i.channel!=='message'||i.account!==account||!i.context||!acceptedFeatures(i,recipeId==='ms-communications-api'?['embedded-communications','supported-architecture']:['channel-accounts','workflow-flows','webhook-delivery']))continue;
   const workflow=c.operations?.jobs.find(j=>j.interaction===i.id&&['accepted','delivered'].includes(j.status)&&j.attempts>=2),receipt=c.channels?.webhooks.deliveries.find(r=>r.interactionId===i.id||r.caseId===i.caseId);
   if(workflow&&receipt&&receipt.caseId===i.caseId&&pair.job.messageCharged&&i.trace.some(t=>t.code==='HTTP_503'&&t.job===workflow.id&&t.attempt===1)&&i.trace.some(t=>t.code==='RETRY_SCHEDULED')&&i.trace.some(t=>t.code==='HTTP_202'&&t.job===workflow.id))return result({kind:'channel-case-retry-and-receipt',...pair,workflow,receipt,account:c.channels.accounts[account]});
  }return null;
 }
 if(['cisco-contact-centre','cisco-local-speech'].includes(recipeId)){
  for(const pair of pairs){const i=pair.interaction,recording=c.records.find(r=>r.interaction===i.id&&r.kind==='recording'&&!r.deleted),transcript=c.records.find(r=>r.interaction===i.id&&r.kind==='transcription'&&!r.deleted),processing=c.information?.jobs.find(j=>j.interaction===i.id&&j.status==='complete');
   if(!recording||!transcript||!processing||recipeId==='cisco-local-speech'&&!processing.speechModel||recipeId==='cisco-contact-centre'&&!acceptedFeatures(i,['quality-review']))continue;
   return result({kind:recipeId==='cisco-local-speech'?'model-bound-stored-transcript':'captured-contact-processing',...pair,recording,transcript,processing});
  }return null;
 }
 if(recipeId==='cisco-provider-operations'){
  const policy=s.providerAutomation.find(a=>a.projectId===p.id),action=policy?.actions.find(a=>a.kind==='migration'),work=s.providerCampaign.projects.find(p=>p.id===action?.projectId&&p.status==='complete'),statement=providerModel().customers.find(c=>c.id==='starter-customer')?.wholesaleStatement;
  if(!action||!work||!statement?.available||!statement.rows.length||SOC.operations.platform(c,'bea')!=='migration-phone')return null;
  return result({kind:'scoped-fulfilled-order-and-wholesale-statement',policy,action,work,posting:s.business.ledger.find(e=>e.id===work.postingId),statement,history:s.providerCampaign.customers[0].history,ledger:s.business.ledger.filter(e=>e.customerId==='starter-customer')});
 }
 throw new Error('No capability evidence contract for '+recipeId);
}
