 const state=()=>page.evaluate(()=>{const s=SCP.state,c=s.portfolio.customers[0]?.root;return {clock:s.clock,cash:s.business.balance.cash,projects:structuredClone(s.providerCampaign.projects),ledger:structuredClone(s.business.ledger),integration:structuredClone(providerModel().customers[0]?.serviceIntegration),interactions:structuredClone(c?.interactions||[]),records:structuredClone(c?.records||[]),jobs:structuredClone(s.providerCampaign.jobs),reviews:structuredClone(c?.providerReviews||[]),deployments:structuredClone(c?.products?.deployments||[])};});
 const step=async name=>{row.steps.push({name,...await state()});await snap(page,row,name);};
 const pause=async()=>{if(await page.evaluate(()=>!!SCP.speed))await click(page,'[data-provider-action="pause"]');await page.waitForFunction(()=>!SCP.speed&&!SCP.busy);};
 const waitUntil=async(predicate,arg)=>{const deadline=Date.now()+180000;while(!await page.evaluate(predicate,arg)){
  if(Date.now()>deadline)throw new Error('UC–CC integration journey timed out waiting for actual delivery');
  const incident=await page.evaluate(()=>SCP.state.providerCampaign.incidents.find(i=>i.status==='active')?.id);
  if(incident){await pause();await click(page,'[data-provider-action="drawer"][data-provider-value="incidents"]');await click(page,`[data-provider-action="select-incident"][data-id="${incident}"]`);await click(page,`.provider-inspector [data-provider-action="ack-incident"][data-id="${incident}"]`);await operation('repair');continue;}
  const renewal=await page.evaluate(()=>SCP.state.providerCampaign.customers.find(c=>c.status==='renewal')?.id);if(renewal){await pause();await selectMapCustomer(page,renewal);await click(page,`.provider-inspector [data-provider-action="renew"][data-id="${renewal}"]`);await page.waitForFunction(id=>SCP.state.providerCampaign.customers.find(c=>c.id===id).status==='active',renewal);continue;}
  if(!await page.evaluate(()=>!!SCP.speed))await click(page,'[data-provider-action="speed"][data-provider-value="8"]');await page.waitForTimeout(100);
 }await pause();};
 const operation=async(id,{status='complete',open=false}={})=>{await pause();if(!open)await openOperation(page,id);const q=await page.evaluate(()=>structuredClone(SOC_PROVIDER_UI.view().quote));assert.deepEqual(q.blockers,[]);const before=await state();await click(page,'[data-provider-action="confirm-quote"]');await page.waitForFunction(({id,prior})=>SCP.state.providerCampaign.projects.some(p=>p.operationId===id&&!prior.includes(p.id)),{id,prior:before.projects.map(p=>p.id)});const funded=await state(),project=funded.projects.find(p=>p.operationId===id&&!before.projects.some(old=>old.id===p.id));assert.equal(funded.cash,before.cash-q.setupCents);assert.equal(funded.ledger.find(e=>e.id===project.postingId).cents,q.setupCents);await waitUntil(({id,status})=>SCP.state.providerCampaign.projects.find(p=>p.id===id)?.status===status,{id:project.id,status});return project.id;};
